### ✅ ALWAYS: Implement Refresh Token Pattern

```typescript
import jwt from 'jsonwebtoken';
import crypto from 'crypto';

// ✅ Generate token pair
async function generateTokenPair(userId: string) {
  // ✅ Short-lived access token
  const accessToken = jwt.sign(
    { userId, type: 'access' },
    process.env.JWT_SECRET!,
    { expiresIn: '15m' }
  );

  // ✅ Long-lived refresh token
  const refreshToken = jwt.sign(
    { userId, type: 'refresh' },
    process.env.JWT_REFRESH_SECRET!,
    { expiresIn: '7d' }
  );

  // ✅ Store refresh token hash in database (for revocation)
  const refreshTokenHash = crypto
    .createHash('sha256')
    .update(refreshToken)
    .digest('hex');

  await db.refreshTokens.create({
    data: {
      userId,
      tokenHash: refreshTokenHash,
      expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
    },
  });

  return { accessToken, refreshToken };
}

// ✅ Login with refresh token
app.post('/api/login', async (req, res) => {
  const { email, password } = req.body;

  const user = await validateUser(email, password);

  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const { accessToken, refreshToken } = await generateTokenPair(user.id);

  // ✅ Set both tokens as httpOnly cookies
  res.cookie('access_token', accessToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 15 * 60 * 1000, // 15 minutes
  });

  res.cookie('refresh_token', refreshToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
    path: '/api/refresh', // Only sent to refresh endpoint
  });

  res.json({ message: 'Login successful' });
});

// ✅ Refresh access token
app.post('/api/refresh', async (req, res) => {
  const refreshToken = req.cookies.refresh_token;

  if (!refreshToken) {
    return res.status(401).json({ error: 'No refresh token' });
  }

  try {
    // ✅ Verify refresh token
    const decoded = jwt.verify(
      refreshToken,
      process.env.JWT_REFRESH_SECRET!
    ) as { userId: string; type: string };

    if (decoded.type !== 'refresh') {
      return res.status(401).json({ error: 'Invalid token type' });
    }

    // ✅ Check if refresh token is still valid in database
    const refreshTokenHash = crypto
      .createHash('sha256')
      .update(refreshToken)
      .digest('hex');

    const storedToken = await db.refreshTokens.findFirst({
      where: {
        userId: decoded.userId,
        tokenHash: refreshTokenHash,
        expiresAt: { gt: new Date() },
      },
    });

    if (!storedToken) {
      return res.status(401).json({ error: 'Refresh token revoked or expired' });
    }

    // ✅ Generate new access token
    const accessToken = jwt.sign(
      { userId: decoded.userId, type: 'access' },
      process.env.JWT_SECRET!,
      { expiresIn: '15m' }
    );

    // ✅ Set new access token
    res.cookie('access_token', accessToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 15 * 60 * 1000,
    });

    res.json({ message: 'Token refreshed' });
  } catch (error) {
    return res.status(401).json({ error: 'Invalid refresh token' });
  }
});

// ✅ Revoke refresh tokens on logout
app.post('/api/logout', async (req, res) => {
  const refreshToken = req.cookies.refresh_token;

  if (refreshToken) {
    const refreshTokenHash = crypto
      .createHash('sha256')
      .update(refreshToken)
      .digest('hex');

    // ✅ Delete refresh token from database
    await db.refreshTokens.deleteMany({
      where: { tokenHash: refreshTokenHash },
    });
  }

  // ✅ Clear cookies
  res.clearCookie('access_token');
  res.clearCookie('refresh_token');

  res.json({ message: 'Logged out' });
});
```

**Benefit:** Short-lived access tokens limit damage from theft, refresh tokens can be revoked

