### ✅ ALWAYS: Use Timeouts and Size Limits

```typescript
import { URL } from 'url';

// ✅ Fetch with timeout and size limit
async function safeFetch(
  url: string,
  options: {
    timeout?: number;
    maxSize?: number;
  } = {}
): Promise<string> {
  const timeout = options.timeout || 5000; // 5 seconds default
  const maxSize = options.maxSize || 10 * 1024 * 1024; // 10MB default

  // ✅ Create abort controller for timeout
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeout);

  try {
    const response = await fetch(url, {
      signal: controller.signal,
      redirect: 'manual',
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }

    // ✅ Check content length
    const contentLength = response.headers.get('content-length');

    if (contentLength && parseInt(contentLength) > maxSize) {
      throw new Error('Response too large');
    }

    // ✅ Stream with size limit
    const reader = response.body!.getReader();
    const chunks: Uint8Array[] = [];
    let receivedSize = 0;

    while (true) {
      const { done, value } = await reader.read();

      if (done) break;

      chunks.push(value);
      receivedSize += value.length;

      // ✅ Enforce size limit during streaming
      if (receivedSize > maxSize) {
        reader.cancel();
        throw new Error('Response too large');
      }
    }

    // Combine chunks
    const combined = new Uint8Array(receivedSize);
    let position = 0;

    for (const chunk of chunks) {
      combined.set(chunk, position);
      position += chunk.length;
    }

    return new TextDecoder().decode(combined);
  } finally {
    clearTimeout(timeoutId);
  }
}

app.post('/api/fetch-url', async (req, res) => {
  const { url } = req.body;

  if (!(await isValidExternalUrl(url))) {
    return res.status(400).json({ error: 'URL not allowed' });
  }

  try {
    const data = await safeFetch(url, {
      timeout: 10000, // 10 seconds
      maxSize: 5 * 1024 * 1024, // 5MB
    });

    res.send(data);
  } catch (error) {
    res.status(500).json({ error: 'Fetch failed' });
  }
});
```

**Benefit:** Prevents slowloris attacks and resource exhaustion

