## Common Interactions

### Click

```tsx
const user = userEvent.setup();

// Single click
await user.click(screen.getByRole('button'));

// Double click
await user.dblClick(screen.getByRole('button'));

// Right click
await user.pointer({ keys: '[MouseRight]', target: element });
```

### Type and Keyboard

```tsx
const user = userEvent.setup();
const input = screen.getByRole('textbox');

// Type text (triggers focus, keydown, keypress, input, keyup)
await user.type(input, 'Hello world');

// Clear input
await user.clear(input);

// Type with special keys
await user.type(input, 'Test{Enter}'); // Press Enter
await user.type(input, '{Shift}hello{/Shift}'); // HELLO

// Keyboard shortcuts
await user.keyboard('{Control>}a{/Control}'); // Ctrl+A
await user.keyboard('{Alt>}{Shift>}k{/Shift}{/Alt}'); // Alt+Shift+K
```

### Select/Dropdown

```tsx
const user = userEvent.setup();

// Select by label text
await user.selectOptions(
  screen.getByRole('combobox'),
  'Option Label'
);

// Select by value
await user.selectOptions(
  screen.getByRole('combobox'),
  'option-value'
);

// Multi-select
await user.selectOptions(
  screen.getByRole('listbox'),
  ['Option 1', 'Option 2']
);
```

### Checkbox/Radio

```tsx
const user = userEvent.setup();

// Check checkbox
await user.click(screen.getByRole('checkbox'));

// Or more explicit
const checkbox = screen.getByRole('checkbox');
if (!checkbox.checked) {
  await user.click(checkbox);
}

// Radio button
await user.click(screen.getByRole('radio', { name: /option a/i }));
```

### Upload File

```tsx
const user = userEvent.setup();
const file = new File(['content'], 'test.txt', { type: 'text/plain' });

const input = screen.getByLabelText(/upload file/i);
await user.upload(input, file);

// Multiple files
await user.upload(input, [file1, file2]);
```

### Hover and Unhover

```tsx
const user = userEvent.setup();

// Hover over element
await user.hover(screen.getByRole('button'));
expect(screen.getByRole('tooltip')).toBeInTheDocument();

// Unhover
await user.unhover(screen.getByRole('button'));
expect(screen.queryByRole('tooltip')).not.toBeInTheDocument();
```

### Copy/Paste

```tsx
